// Real Mufasa Safaris & Tours badge logo, embedded as a base64 data URL
// rather than read from `public/` via fs at request time -- same
// production-safety reasoning as pdf-fonts.ts's font embedding: Vercel's
// output-file-tracer has no reliable way to discover a runtime fs read
// against a `public/` path from inside a serverless function bundle (that
// directory is served by Vercel's CDN, not guaranteed present on the
// function's own filesystem), so a path-based read that works locally can
// silently 404 in production. A source-embedded data URL sidesteps that
// entirely. Consumed by every Node-runtime PDF renderer (finance/
// package-summary-pdf.tsx, invoicing/invoice-pdf.tsx, itinerary/
// itinerary-summary-pdf.tsx, itinerary/map-pdf.tsx) and by the package
// opengraph-image.tsx fallback plate (also nodejs runtime). The larger
// web-display copy of this same badge (header/footer/staff chrome) lives
// as a normal static file instead, at public/images/brand/mufasa-logo.png
// -- those are plain browser-fetched <img>/next/image references, not a
// server-side fs read, so they don't hit this failure mode.
//
// White square background removed (flood-filled + feathered to alpha);
// everything else -- ring border, plum ring, gold disc, lion art -- is
// untouched, per explicit user direction.
export const BRAND_LOGO_DATA_URI =
  "data:image/png;base64,";
